/* Helpers for C generated by tools/recomp (one ARM instruction = a few statements over NjCtx *c).
 * Flags live in c->n/z/c/v/q (0 or 1) and c->ge (GE[3:0]); semantics follow the ARMv7-A ARM. */
#ifndef NJ_RECOMP_RT_H
#define NJ_RECOMP_RT_H

#include <stdint.h>

#include "nj/guest.h"

/* ---- conditions ---- */
#define NJ_COND_EQ(c) ((c)->z)
#define NJ_COND_NE(c) (!(c)->z)
#define NJ_COND_HS(c) ((c)->c)
#define NJ_COND_LO(c) (!(c)->c)
#define NJ_COND_MI(c) ((c)->n)
#define NJ_COND_PL(c) (!(c)->n)
#define NJ_COND_VS(c) ((c)->v)
#define NJ_COND_VC(c) (!(c)->v)
#define NJ_COND_HI(c) ((c)->c && !(c)->z)
#define NJ_COND_LS(c) (!(c)->c || (c)->z)
#define NJ_COND_GE(c) ((c)->n == (c)->v)
#define NJ_COND_LT(c) ((c)->n != (c)->v)
#define NJ_COND_GT(c) (!(c)->z && (c)->n == (c)->v)
#define NJ_COND_LE(c) ((c)->z || (c)->n != (c)->v)

/* ---- arithmetic with flags (AddWithCarry) ---- */
static inline uint32_t nj_awc(NjCtx *c, uint32_t a, uint32_t b, uint32_t carry_in) {
    uint64_t wide = (uint64_t)a + b + carry_in;
    uint32_t r = (uint32_t)wide;
    c->n = r >> 31;
    c->z = r == 0;
    c->c = (uint32_t)(wide >> 32);
    c->v = ((~(a ^ b)) & (a ^ r)) >> 31;
    return r;
}
static inline uint32_t nj_adds(NjCtx *c, uint32_t a, uint32_t b) { return nj_awc(c, a, b, 0); }
static inline uint32_t nj_adcs(NjCtx *c, uint32_t a, uint32_t b) { return nj_awc(c, a, b, c->c); }
static inline uint32_t nj_subs(NjCtx *c, uint32_t a, uint32_t b) { return nj_awc(c, a, ~b, 1); }
static inline uint32_t nj_sbcs(NjCtx *c, uint32_t a, uint32_t b) { return nj_awc(c, a, ~b, c->c); }

/* N, Z from the result, C from the shifter (V unchanged). */
static inline void nj_logic_flags(NjCtx *c, uint32_t r, uint32_t carry) {
    c->n = r >> 31;
    c->z = r == 0;
    c->c = carry;
}

/* ---- shifter ---- */
enum { NJ_LSL, NJ_LSR, NJ_ASR, NJ_ROR, NJ_RRX };

/* Shift with carry out; *carry holds the incoming C and receives the shifter carry. `amount` is the full
 * amount (register shifts pass Rs & 0xff, so 0, 32 and > 32 follow the register-shift rules). */
static inline uint32_t nj_shift_c(int kind, uint32_t v, uint32_t amount, uint32_t *carry) {
    switch (kind) {
    case NJ_LSL:
        if (amount == 0) return v;
        if (amount < 32) { *carry = (v >> (32 - amount)) & 1; return v << amount; }
        *carry = amount == 32 ? (v & 1) : 0;
        return 0;
    case NJ_LSR:
        if (amount == 0) return v;
        if (amount < 32) { *carry = (v >> (amount - 1)) & 1; return v >> amount; }
        *carry = amount == 32 ? (v >> 31) : 0;
        return 0;
    case NJ_ASR:
        if (amount == 0) return v;
        if (amount < 32) { *carry = (v >> (amount - 1)) & 1; return (uint32_t)((int32_t)v >> amount); }
        *carry = v >> 31;
        return (uint32_t)((int32_t)v >> 31);
    case NJ_ROR:
        if (amount == 0) return v;
        amount &= 31;
        if (amount == 0) { *carry = v >> 31; return v; }
        v = (v >> amount) | (v << (32 - amount));
        *carry = v >> 31;
        return v;
    default: { /* RRX */
        uint32_t r = (*carry << 31) | (v >> 1);
        *carry = v & 1;
        return r;
    }
    }
}

/* Shift without carry out (non-flag-setting and arithmetic instructions). RRX reads C. */
static inline uint32_t nj_shift(const NjCtx *c, int kind, uint32_t v, uint32_t amount) {
    uint32_t carry = c->c;
    return nj_shift_c(kind, v, amount, &carry);
}

#endif
